using System;using System.Linq;using System.Collections.Generic;using UnityEngine;using HarmonyLib;using MDPro3.Duel;using MDPro3.DuelEditor;using Il2CppInterop.Runtime;
namespace DuelStructure {
 static class NativeLogHistory {
  sealed class Row {public int point;public GameObject go;public bool summon,search,opening;public string edit;public NativeLogPerspective.Snapshot perspective;}
  static readonly List<Row> rows=new List<Row>();static readonly Dictionary<int,Queue<int>> emissions=new Dictionary<int,Queue<int>>();static readonly Dictionary<IntPtr,int> packages=new Dictionary<IntPtr,int>();static RectTransform archive;static int activePoint;static string activeEdit;static bool activeSummon,activeSearch,activeOpening;static readonly HashSet<int> openingPoints=new HashSet<int>();static bool allowClear,addingOpening,openingReady;static uint[][] openingCards;
  static NativeLogArchive.Document pendingHistory;
  static DuelLog Log=>MDPro3.Program.instance?.ocgcore?.servantUI==null?null:MDPro3.Program.instance.ocgcore.GetUI<MDPro3.UI.ServantUI.OcgCoreUI>().DuelLog;
  public static bool KeepLog=>Host.Session!=null&&!allowClear;
  public static void Reset(){NativeLogArchive.Reset();pendingHistory=null;rows.Clear();emissions.Clear();packages.Clear();activePoint=0;activeEdit=null;activeOpening=false;openingPoints.Clear();openingCards=null;openingReady=false;addingOpening=false;if(archive!=null)UnityEngine.Object.Destroy(archive.gameObject);archive=null;allowClear=true;try{Log?.ClearLog();}finally{allowClear=false;}}
  public static void SetOpening(EditorCard[] cards){openingCards=new uint[2][];for(int p=0;p<2;p++)openingCards[p]=cards.Where(c=>c.Player==p&&c.Location==2).OrderBy(c=>c.Sequence).Select(c=>c.Code).ToArray();}
  public static void EnsureOpening(){ImportPending();if(openingReady||openingCards==null||!Host.InDuel||!MDPro3.Program.instance.ocgcore.DuelBGManager.loaded)return;var log=Log;if(log==null)return;if(Host.Session.Setup.OpeningProcess){LogMessage.life0=LogMessage.life1=8000;openingReady=true;return;}int previous=activePoint;bool summon=activeSummon,search=activeSearch;activePoint=1;activeSummon=activeSearch=false;addingOpening=true;try{LogMessage.life0=LogMessage.life1=8000;for(int p=0;p<2;p++){int local=p==Host.Session.View?0:1;log.AddLpChangeMessageToLog(local,"开局基本分",8000,false,false);Capture();if(Host.Session.Setup.OpeningProcess)continue;var list=new Il2CppSystem.Collections.Generic.List<int>();foreach(uint code in openingCards[p])list.Add((int)code);if(list.Count>0)log.AddOpeningDrawMessageToLog(list.Cast<Il2CppSystem.Collections.Generic.IReadOnlyList<int>>(),new MDPro3.GPS{controller=(uint)local,location=2},"开局手牌");else log.AddTextMessageToLog("玩家 "+(p+1)+" 开局手牌：0 张",false,true);Capture();}openingReady=true;Restore(Host.Session.Number);}finally{addingOpening=false;activePoint=previous;activeSummon=summon;activeSearch=search;}}
  public static void RecordEdit(string text,Action<DuelLog> render,string detail=""){var log=Log;if(log==null)return;Capture();int previous=activePoint;bool summon=activeSummon,search=activeSearch,opening=activeOpening;string edit=activeEdit;activePoint=Host.Session.Number;activeSummon=activeSearch=activeOpening=false;activeEdit=text;try{render(log);Capture();foreach(var row in rows.Where(r=>r.edit==text&&r.point==Host.Session.Number&&r.go!=null))StyleEdit(row.go,detail);Restore(Host.Session.Number);}finally{activePoint=previous;activeSummon=summon;activeSearch=search;activeOpening=opening;activeEdit=edit;}}
  static void StyleEdit(GameObject go,string detail){
   foreach(var label in go.GetComponentsInChildren<UnityEngine.UI.Text>(true)){label.resizeTextForBestFit=false;label.fontSize=Math.Max(18,label.fontSize);label.horizontalOverflow=HorizontalWrapMode.Wrap;}
   var reason=go.transform.childCount>3?go.transform.GetChild(3).GetComponent<UnityEngine.UI.Text>():null;if(reason!=null)reason.fontSize=18;
   if(string.IsNullOrWhiteSpace(detail))return;
   Canvas.ForceUpdateCanvases();var root=go.GetComponent<RectTransform>();var textGo=new GameObject("EditorChangeDetails");var rect=textGo.AddComponent(Il2CppType.Of<RectTransform>()).Cast<RectTransform>();rect.SetParent(root,false);rect.anchorMin=new Vector2(0,1);rect.anchorMax=new Vector2(1,1);rect.pivot=new Vector2(0,1);rect.offsetMin=new Vector2(12,0);rect.offsetMax=new Vector2(-12,0);
   var labelText=textGo.AddComponent(Il2CppType.Of<UnityEngine.UI.Text>()).Cast<UnityEngine.UI.Text>();labelText.font=go.GetComponentInChildren<UnityEngine.UI.Text>(true).font;labelText.fontSize=18;labelText.color=Color.white;labelText.alignment=TextAnchor.UpperLeft;labelText.horizontalOverflow=HorizontalWrapMode.Wrap;labelText.verticalOverflow=VerticalWrapMode.Overflow;labelText.raycastTarget=false;labelText.text=detail;
   float original=root.rect.height;float height=Math.Max(24,labelText.preferredHeight)+8;root.sizeDelta=new Vector2(root.sizeDelta.x,original+height);rect.anchoredPosition=new Vector2(12,-original);rect.sizeDelta=new Vector2(-24,height);
  }
  public static bool EditorRowsNativeAndReadable=>rows.Where(r=>r.edit!=null&&r.go!=null).All(r=>r.go.GetComponentsInChildren<UnityEngine.UI.Text>(true).All(t=>!t.resizeTextForBestFit&&t.fontSize>=18)&&(r.go.GetComponentInChildren<UnityEngine.UI.RawImage>(true)!=null||r.edit.Contains("LP 设为")));
  public static int RecordedEditCount=>rows.Count(r=>r.edit!=null&&r.go!=null);
  public static string[] VisibleEdits=>rows.Where(r=>r.edit!=null&&r.go!=null&&r.go.transform.parent.Pointer==Log.scrollRect.content.Pointer).OrderBy(r=>r.point).Select(r=>r.edit).ToArray();
  public static int OpeningRows=>rows.FindAll(r=>r.opening&&r.go!=null&&r.go.transform.parent.Pointer==Log.scrollRect.content.Pointer).Count;
  public static void Stamp(int message){if(!emissions.TryGetValue(message,out var queue)){queue=new Queue<int>();emissions[message]=queue;}queue.Enqueue(Host.Session.Number+1);if(message==90&&Host.Session.Setup.OpeningProcess&&EditorNative.editor_turn_id(Host.Session.Handle)==0)openingPoints.Add(Host.Session.Number+1);}
  public static void Tag(MDPro3.Package p){int n=Host.Session.Number;if(emissions.TryGetValue(p.Function,out var q)&&q.Count>0)n=q.Dequeue();packages[p.Pointer]=n;}
  public static void Begin(MDPro3.Package p){NativeLogPerspective.SyncDirection();activePoint=packages.TryGetValue(p.Pointer,out int n)?n:Host.Session.Number;packages.Remove(p.Pointer);activeOpening=p.Function==90&&openingPoints.Contains(activePoint);activeSummon=p.Function==60||p.Function==61;var bytes=p.Data.Get().ToArray();activeSearch=p.Function==50&&bytes.Length>=16&&bytes[5]==1&&bytes[9]==2&&(BitConverter.ToUInt32(bytes,12)&0x2000000)==0;}
  public static void Add(GameObject go){if(go==null||rows.Any(r=>r.go!=null&&r.go.Pointer==go.Pointer))return;rows.Add(new Row{point=activePoint>0?activePoint:Host.Session.Number,go=go,summon=activeSummon,search=activeSearch,opening=addingOpening||activeOpening,edit=activeEdit,perspective=new NativeLogPerspective.Snapshot(go)});Restore(Host.Session.Number);}
  public static void Capture(){var log=Log;if(log==null)return;for(int i=0;i<log.scrollRect.content.childCount;i++){var go=log.scrollRect.content.GetChild(i).gameObject;if(!rows.Exists(r=>r.go!=null&&r.go.Pointer==go.Pointer))rows.Add(new Row{point=activePoint>0?activePoint:Host.Session.Number,go=go,summon=activeSummon,search=activeSearch,opening=addingOpening||activeOpening,edit=activeEdit,perspective=new NativeLogPerspective.Snapshot(go)});}}
  public static void Stash(){Capture();var log=Log;if(log==null)return;if(archive==null)Restore(Host.Session.Number);foreach(var row in rows)if(row.go!=null)row.go.transform.SetParent(archive,false);log.fullHeight=0;}
  public static byte[] SaveArchive(){ImportPending();if(pendingHistory!=null)return NativeLogArchive.Encode(pendingHistory);Capture();var document=new NativeLogArchive.Document{Point=Host.Session.Number,State=NativeLogArchive.CaptureContext()};foreach(var row in rows.Where(r=>r.go!=null&&r.point<=Host.Session.Number).OrderBy(r=>r.point)){row.perspective?.Apply();document.Rows.Add(new NativeLogArchive.Entry{Point=row.point,View=Host.Session.View,Summon=row.summon,Search=row.search,Opening=row.opening,Edit=row.edit,Prefab=NativeLogArchive.Prefab(row.go),Root=NativeLogArchive.Capture(row.go)});}return NativeLogArchive.Encode(document);}
  public static void ValidateArchive(byte[] bytes,int point){NativeLogArchive.Decode(bytes,point);}
  public static void LoadArchive(byte[] bytes){pendingHistory=NativeLogArchive.Decode(bytes,Host.Session.Number);NativeLogArchive.QueueContext(pendingHistory.State);DiscardAfter(0);openingReady=true;}
  static void ImportPending(){if(pendingHistory==null||!Host.DuelUIReady||Log==null)return;var document=pendingHistory;pendingHistory=null;NativeLogArchive.BeginImport();foreach(var saved in document.Rows){var go=NativeLogArchive.Create(saved);go.transform.SetParent(Log.scrollRect.content,false);rows.Add(new Row{point=saved.Point,go=go,summon=saved.Summon,search=saved.Search,opening=saved.Opening,edit=saved.Edit,perspective=new NativeLogPerspective.Snapshot(go,saved.View)});}Restore(Host.Session.Number);}
  public static int KnownCardFaces=>rows.Where(r=>r.go!=null&&r.point<=Host.Session.Number).Sum(r=>r.go.GetComponentsInChildren<UnityEngine.UI.RawImage>(true).Count(i=>NativeLogArchive.KnownCode(i)>0));
  public static bool HistoryPending=>pendingHistory!=null;
  public static string HistorySignature(){var text=string.Join("\n",rows.Where(r=>r.go!=null&&r.point<=Host.Session.Number).OrderBy(r=>r.point).Select(r=>r.point+"|"+r.summon+"|"+r.search+"|"+r.opening+"|"+r.edit+"|"+string.Join("/",r.go.GetComponentsInChildren<UnityEngine.UI.Text>(true).Select(t=>t.text))+"|"+string.Join(",",r.go.GetComponentsInChildren<UnityEngine.UI.RawImage>(true).Select(i=>NativeLogArchive.KnownCode(i)))));using(var hash=System.Security.Cryptography.SHA256.Create())return Convert.ToBase64String(hash.ComputeHash(System.Text.Encoding.UTF8.GetBytes(text)));}
  public static void Loaded(int shared){pendingHistory=null;NativeLogArchive.QueueContext(null);DiscardAfter(shared);emissions.Clear();packages.Clear();activePoint=0;activeEdit=null;activeSummon=activeSearch=activeOpening=false;if(shared==0)openingReady=true;}
  public static int VisibleReasonCount(string reason)=>rows.Count(r=>r.go!=null&&r.go.transform.parent.Pointer==Log.scrollRect.content.Pointer&&r.go.name.StartsWith("DuelLogSingleCard")&&r.go.transform.childCount>3&&r.go.transform.GetChild(3).GetComponent<UnityEngine.UI.Text>()!=null&&r.go.transform.GetChild(3).GetComponent<UnityEngine.UI.Text>().text==reason);
  public static void DiscardAfter(int point){for(int i=rows.Count-1;i>=0;i--)if(rows[i].point>point){if(rows[i].go!=null){rows[i].go.transform.SetParent(null,false);rows[i].go.SetActive(false);UnityEngine.Object.Destroy(rows[i].go);}rows.RemoveAt(i);}openingPoints.RemoveWhere(p=>p>point);Restore(point);}
  public static void Restore(int point){var log=Log;if(log==null)return;if(archive==null){var go=new GameObject("EditorArchivedDuelLog");archive=go.AddComponent(Il2CppType.Of<RectTransform>()).Cast<RectTransform>();archive.SetParent(log.transform,false);go.SetActive(false);}float y=0;foreach(var row in rows.OrderBy(r=>r.point)){if(row.go==null)continue;row.perspective?.Apply();var rect=row.go.GetComponent<RectTransform>();if(row.point>point){rect.SetParent(archive,false);continue;}rect.SetParent(log.scrollRect.content,false);rect.anchoredPosition=new Vector2(rect.anchoredPosition.x,-y);y+=rect.rect.height*Math.Abs(rect.localScale.y);}log.fullHeight=y;log.scrollRect.content.sizeDelta=new Vector2(log.scrollRect.content.sizeDelta.x,y);if(log.showing)log.Refresh(0);}
  public static int VisibleSummons=>rows.FindAll(r=>r.summon&&r.go!=null&&r.go.transform.parent.Pointer==Log.scrollRect.content.Pointer).Count;
  public static bool SearchSidesMatchCurrentView{get{var search=rows.Where(r=>r.search&&r.go!=null&&r.go.transform.parent.Pointer==Log.scrollRect.content.Pointer).ToArray();return search.Any(r=>r.perspective.CanonicalOwner==0)&&search.Any(r=>r.perspective.CanonicalOwner==1)&&search.All(r=>r.perspective.SideMatchesCurrentView);}}
  public static int VisibleSearches=>rows.FindAll(r=>r.search&&r.go!=null&&r.go.transform.parent.Pointer==Log.scrollRect.content.Pointer).Count;
  public static int VisibleRows=>Log==null?0:Log.scrollRect.content.childCount;
 }
 [HarmonyPatch(typeof(DuelLog),nameof(DuelLog.ClearLog))]class KeepEditorDuelLog{static bool Prefix()=>!NativeLogHistory.KeepLog;}
 [HarmonyPatch(typeof(DuelLog),nameof(DuelLog.AddLog))]class TrackEditorDuelLog{static void Postfix(GameObject item){if(Host.Session!=null)NativeLogHistory.Add(item);}}
 [HarmonyPatch(typeof(MDPro3.Servant.OcgCore),nameof(MDPro3.Servant.OcgCore.AddPackage))]class TagEditorLogPackage{static void Prefix(MDPro3.Package p){if(Host.Session!=null)NativeLogHistory.Tag(p);}}
 [HarmonyPatch(typeof(MessageDispatcher),nameof(MessageDispatcher.Process))]class BeginEditorLogPackage{static void Prefix(MDPro3.Package p){if(Host.Session!=null)NativeLogHistory.Begin(p);}static void Postfix(){if(Host.Session!=null)NativeLogHistory.Capture();}}
}
